        }
        return clusterService.getClusterSettings().get(EqlPlugin.DEFAULT_ALLOW_PARTIAL_SEQUENCE_RESULTS);
    }

@Override
    public BreakerSettings getCircuitBreaker(Settings settings) {
        return eqlPlugin.getCircuitBreaker(settings);
    }
